            ['section' => 'Comprehension', 'type' => 'matching', 'question_text' => 'Match each figure to their part.', 'match_pairs' => [['left' => 'Androclus', 'right' => 'Poor slave whose kindness won him liberty and a strange friend'], ['left' => 'His master', 'right' => 'Cruel man whose harshness drove the slave to the forest'], ['left' => 'The lion', 'right' => 'Beast that remembered its healer before all of Rome'], ['left' => 'The soldiers', 'right' => 'Passing troop that carried the runaway back to the city']]],
