            ['section' => 'Comprehension', 'type' => 'matching', 'question_text' => 'Match each figure to their part.', 'match_pairs' => [['left' => 'Silverspot', 'right' => 'Old chief who commanded two hundred crows like a general'], ['left' => 'The horned owl', 'right' => 'Double-toed night enemy that ended the long reign'], ['left' => 'The old resident', 'right' => 'Neighbor who remembered the crow flying there twenty years'], ['left' => 'The narrator', 'right' => 'Watcher who pieced the story together from seasons of study']]],
